item.aggregated_output:
1: [CmdletBinding()]
2: param(
3:     [switch]$SkipDocker,
4:     [switch]$SkipEnvironmentFile
5: )
6: 
7: $ErrorActionPreference = 'Stop'
8: Set-StrictMode -Version 2.0
9: 
10: $repositoryRoot = Split-Path -Parent $PSScriptRoot
11: 
12: function Assert-Command {
13:     param([Parameter(Mandatory = $true)][string]$Name)
14:     if (-not (Get-Command $Name -ErrorAction SilentlyContinue)) {
15:         throw "Required command not found: $Name"
16:     }
17: }
18: 
19: Assert-Command -Name 'java'
20: $javaOutput = (& java --version | Out-String)
21: $javaExitCode = $LASTEXITCODE
22: if ($javaExitCode -ne 0) {
23:     throw 'java --version failed'
24: }
25: if ($javaOutput -notmatch '(?m)^\s*(?:java|openjdk)\s+(?:version\s+)?["]?25(?:[.\-"\s]|$)') {
26:     throw "Java 25 LTS is required. Detected output: $($javaOutput.Trim())"
27: }
28: 
29: if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'mvnw.cmd') -PathType Leaf)) {
30:     throw 'mvnw.cmd is missing'
31: }
32: if (-not (Test-Path -LiteralPath (Join-Path $repositoryRoot 'pom.xml') -PathType Leaf)) {
33:     throw 'pom.xml is missing'
34: }
35: 
36: if (-not $SkipEnvironmentFile) {
37:     $envPath = Join-Path $repositoryRoot '.env'
38:     if (-not (Test-Path -LiteralPath $envPath -PathType Leaf)) {
39:         throw 'Missing .env. Run scripts\Initialize-LocalConfig.ps1 first.'
40:     }
41: }
42: 
43: if (-not $SkipDocker) {
44:     Assert-Command -Name 'docker'
45:     & docker info *> $null
46:     if ($LASTEXITCODE -ne 0) {
47:         throw 'Docker Desktop is not ready'
48:     }
49:     & docker compose version *> $null
50:     if ($LASTEXITCODE -ne 0) {
51:         throw 'docker compose is not available'
52:     }
53: 
54:     Push-Location $repositoryRoot
55:     try {
56:         & docker compose --env-file .env config --quiet
57:         if ($LASTEXITCODE -ne 0) {
58:             throw 'compose.yaml validation failed'
59:         }
60:     }
61:     finally {
62:         Pop-Location
63:     }
64: }
65: 
66: Write-Host 'PREFLIGHT_RESULT=PASS'
67: Write-Host 'JAVA_TARGET=25'
68: Write-Host "DOCKER_CHECKED=$(-not $SkipDocker)"
